const lightOf = (t) => t.instances.scene.get().nodes.find((n) => n.light && n.light.type === 'directional');
const setKey = (t, v) => { const l = lightOf(t); if (l) t.instances.scene.update(l.id, { light: { intensity: v } }); };
const panel = t3template.addPanel({ title: 'Lighting', position: 'top' });
const key = t3template.addControl({ id: 'keyLight', label: 'Key Light', type: 'slider', min: 0, max: 3, step: 0.05, default: 1.2, panel, onChange(v, t) { setKey(t, v); t.refresh(); } });
t3template.addControl({ id: 'stamp', label: 'Stamp Exports', type: 'toggle', default: true, panel });
setKey(t3template, key.get());
t3template.refresh();
t3template.addImageStage('stamp', (ctx, controls) => {
  if (!controls.stamp) return;
  const g = ctx.context;
  const pad = 24 * ctx.scale;
  g.font = `${Math.round(22 * ctx.scale)}px sans-serif`;
  g.fillStyle = 'rgba(255, 255, 255, 0.85)';
  g.fillText(`${ctx.kind} · key ${Number(controls.keyLight).toFixed(2)}`, pad, ctx.height - pad);
});
t3template.addToolbarButton('Front View', (t) => { t.instances.scene.set({ camera: { azimuth: 0, elevation: 0 } }); t.refresh(); }, { shortcut: 'shift+f', title: 'Look along the Z axis' });
